insert into public.aa_action_templates (id,hazard_code,sector,title,irr_ref,lead_office,timing,seq) values
('5ae2deec-982c-55b3-bbfe-84342219d0a2'::uuid,null,'Public information','Issue official notice of the declaration and the anticipatory actions being taken','IRR Rule IV Sec. 2(a)','CDRRMO / public information office','on_declaration',1),
('4e49c484-2f22-58a6-83b8-a1950e508f82'::uuid,null,'Public information','Disseminate impact-based advisories on all channels, including GIDA barangays, in Cebuano and accessible formats','IRR Rule IV Sec. 2(b)-(c)','CDRRMO / public information office','before_impact_beyond_3d',2),
('21c95448-208f-5bf7-9479-e95b28e59c62'::uuid,null,'Prepositioning','Preposition food and non-food relief items for the forecast affected population','IRR Rule IV Sec. 3(a)(i); Sec. 6(a)','CSWDO','before_impact_beyond_3d',3),
('11899344-3b71-57fb-a3e1-7e4d5ba6cb3d'::uuid,null,'Prepositioning','Preposition essential medicines, medical supplies and hygiene kits','IRR Rule IV Sec. 3(a)(ii)','CHO','before_impact_beyond_3d',4),
('7e324918-aa34-5567-95ae-d3e750c2b9a6'::uuid,null,'Prepositioning','Stock animal feed, forage, emergency water and mobile veterinary kits','IRR Rule IV Sec. 3(a)(iii)','City Veterinary Office','within_3d',5),
('40a733e1-c1f9-5150-88ad-dddac06aa01d'::uuid,null,'Prepositioning','Secure water and power supply for evacuation centres','IRR Rule IV Sec. 3(a)(iv)','GSO / utility providers','within_3d',6),
('677c73bf-08b8-554d-91cd-eaa49d82f1b3'::uuid,null,'Operational assets','Pre-deploy heavy equipment and road-clearing convoys','IRR Rule IV Sec. 3(b)(i)','City Engineering Office','within_3d',7),
('9de09f25-3b96-5189-a460-5c587bfa8fd6'::uuid,null,'Operational assets','Activate transport for pre-emptive evacuation and supply distribution','IRR Rule IV Sec. 3(b)(ii)','GSO / CDRRMO','within_3d',8),
('dcb2a9be-106b-5755-ba7d-79ffcbf27b2e'::uuid,null,'Operational assets','Preposition response teams and their equipment','IRR Rule IV Sec. 3(b)(iii)','CDRRMO','within_3d',9),
('46bdddd3-cfd9-52b6-946e-1240928a5b50'::uuid,null,'Evacuation','Conduct pre-emptive or forced evacuation of at-risk families','RA 12287 Sec. 9(c); IRR Rule IV Sec. 4(a)(i)','CDRRMO / BDRRMCs','within_3d',10),
('39808646-2329-57ec-98db-a51b88725fbb'::uuid,null,'Evacuation','Assist evacuation of livestock, pets, crops and livelihood assets','IRR Rule IV Sec. 4(a)(ii)','City Agriculture Office / City Veterinary Office','within_3d',11),
('03308757-2668-5749-be21-06f8475d0081'::uuid,null,'Evacuation','Open safe and inclusive evacuation centres and apply CCCM and IDP protection protocols','IRR Rule IV Sec. 4(b)','CSWDO','within_3d',12),
